 let ml = sampleLuminance(coords + vec2<i32>(-1, 0));
 let mr = sampleLuminance(coords + vec2<i32>(1, 0));
 let bl = sampleLuminance(coords + vec2<i32>(-1, 1));
 let bc = sampleLuminance(coords + vec2<i32>(0, 1));
